class Node:
    def __init__(self, value, next=None):
        self.value, self.next = value, next

def make_list(values):
    head = None
    for value in reversed(values):
        head = Node(value, head)
    return head

def to_values(head):
    result = []
    while head is not None:
        result.append(head.value)
        head = head.next
    return result

def find_index(head, target):
    i = 0
    while head is not None:
        if head.value == target:
            return i
        head, i = head.next, i + 1
    return -1

def insert_at(head, index, value):
    if index < 0:
        raise IndexError('index')
    sentinel = Node(None, head)
    pred = sentinel
    for _ in range(index):
        if pred.next is None:
            raise IndexError('index')
        pred = pred.next
    pred.next = Node(value, pred.next)
    return sentinel.next

def erase_at(head, index):
    if index < 0:
        raise IndexError('index')
    sentinel = Node(None, head)
    pred = sentinel
    for _ in range(index):
        if pred.next is None:
            raise IndexError('index')
        pred = pred.next
    victim = pred.next
    if victim is None:
        raise IndexError('index')
    pred.next = victim.next
    victim.next = None  # detached aliases do not retain the suffix
    return sentinel.next

def reverse_list(head):
    prev, curr = None, head
    while curr is not None:
        successor = curr.next
        curr.next = prev
        prev, curr = curr, successor
    return prev

def merge_sorted(a, b):
    # Preconditions: sorted, acyclic, disjoint chains; consumes both inputs.
    sentinel = Node(None)
    tail = sentinel
    while a is not None and b is not None:
        if a.value <= b.value:
            tail.next, a = a, a.next
        else:
            tail.next, b = b, b.next
        tail = tail.next
    tail.next = a if a is not None else b
    return sentinel.next

assert to_values(reverse_list(make_list([10, 20, 30]))) == [30, 20, 10]
assert to_values(merge_sorted(make_list([1, 3]), make_list([2, 3]))) == [1, 2, 3, 3]

