#include <vector>
#include <stdexcept>
#include <cassert>
using namespace std;
struct Node {
    int value;
    Node* next;
    Node(int v, Node* n=nullptr): value(v), next(n) {}
};
// Ownership: caller owns one acyclic chain. No shared tails or concurrent access.
void clear_list(Node*& head) {
    while (head) { Node* next=head->next; delete head; head=next; }
}
Node* make_list(const vector<int>& values) {
    Node* head=nullptr;
    try { for (auto it=values.rbegin(); it!=values.rend(); ++it) head=new Node(*it, head); }
    catch (...) { clear_list(head); throw; }
    return head;
}
vector<int> to_values(Node* head) {
    vector<int> values;
    for (; head; head=head->next) values.push_back(head->value);
    return values;
}
int find_index(Node* head, int target) {
    int i=0;
    for (; head; head=head->next, ++i) if (head->value==target) return i;
    return -1; // teaching chains have at most 10,000 elements
}
Node* insert_at(Node* head, int index, int value) {
    if (index<0) throw out_of_range("index");
    Node sentinel(0, head); Node* pred=&sentinel;
    for (int i=0; i<index; ++i) {
        if (!pred->next) throw out_of_range("index");
        pred=pred->next;
    }
    pred->next=new Node(value, pred->next);
    return sentinel.next;
}
Node* erase_at(Node* head, int index) {
    if (index<0) throw out_of_range("index");
    Node sentinel(0, head); Node* pred=&sentinel;
    for (int i=0; i<index; ++i) {
        if (!pred->next) throw out_of_range("index");
        pred=pred->next;
    }
    Node* victim=pred->next;
    if (!victim) throw out_of_range("index");
    pred->next=victim->next;
    delete victim; // external aliases to this node are now invalid
    return sentinel.next;
}
Node* reverse_list(Node* head) {
    Node* prev=nullptr;
    while (head) {
        Node* successor=head->next;
        head->next=prev;
        prev=head; head=successor;
    }
    return prev;
}
Node* merge_sorted(Node* a, Node* b) {
    // Sorted, acyclic, disjoint inputs. Transfer their ownership to the result.
    Node sentinel(0); Node* tail=&sentinel;
    while (a && b) {
        if (a->value<=b->value) { tail->next=a; a=a->next; }
        else { tail->next=b; b=b->next; }
        tail=tail->next;
    }
    tail->next=a?a:b;
    return sentinel.next;
}
int main() {
    Node* head=make_list({10,20,30});
    head=insert_at(head,1,15); head=erase_at(head,2);
    assert(find_index(head,15)==1);
    head=reverse_list(head);
    assert(to_values(head)==vector<int>({30,15,10}));
    clear_list(head);
    Node* merged=merge_sorted(make_list({1,3}),make_list({2,3}));
    assert(to_values(merged)==vector<int>({1,2,3,3}));
    clear_list(merged);
}

