import java.util.*;
class LinkedLists {
    static class Node {
        int value; Node next;
        Node(int value, Node next) { this.value=value; this.next=next; }
    }
    static Node makeList(int[] values) {
        Node head=null;
        for(int i=values.length-1;i>=0;i--) head=new Node(values[i],head);
        return head;
    }
    static List<Integer> toValues(Node head) {
        List<Integer> out=new ArrayList<>();
        for(;head!=null;head=head.next) out.add(head.value);
        return out;
    }
    static int findIndex(Node head,int target) {
        int i=0;
        for(;head!=null;head=head.next,i++) if(head.value==target) return i;
        return -1;
    }
    static Node predecessor(Node sentinel,int index) {
        if(index<0) throw new IndexOutOfBoundsException();
        Node pred=sentinel;
        for(int i=0;i<index;i++) {
            if(pred.next==null) throw new IndexOutOfBoundsException();
            pred=pred.next;
        }
        return pred;
    }
    static Node insertAt(Node head,int index,int value) {
        Node sentinel=new Node(0,head), pred=predecessor(sentinel,index);
        pred.next=new Node(value,pred.next);
        return sentinel.next;
    }
    static Node eraseAt(Node head,int index) {
        Node sentinel=new Node(0,head), pred=predecessor(sentinel,index);
        Node victim=pred.next;
        if(victim==null) throw new IndexOutOfBoundsException();
        pred.next=victim.next; victim.next=null;
        return sentinel.next;
    }
    static Node reverseList(Node head) {
        Node prev=null;
        while(head!=null) {
            Node successor=head.next;
            head.next=prev; prev=head; head=successor;
        }
        return prev;
    }
    static Node mergeSorted(Node a,Node b) {
        Node sentinel=new Node(0,null), tail=sentinel;
        while(a!=null && b!=null) {
            if(a.value<=b.value) { tail.next=a; a=a.next; }
            else { tail.next=b; b=b.next; }
            tail=tail.next;
        }
        tail.next=a!=null?a:b;
        return sentinel.next;
    }
    public static void main(String[] args) {
        Node head=makeList(new int[]{10,20,30});
        head=insertAt(head,1,15); head=eraseAt(head,2);
        if(findIndex(head,15)!=1) throw new AssertionError("find");
        head=reverseList(head);
        if(!toValues(head).equals(Arrays.asList(30,15,10))) throw new AssertionError("reverse");
        if(!toValues(mergeSorted(makeList(new int[]{1,3}),makeList(new int[]{2,3}))).equals(Arrays.asList(1,2,3,3))) throw new AssertionError("merge");
    }
}

