// ListNode avoids the browser DOM Node name. Inputs are acyclic disjoint chains.
class ListNode {
  constructor(public value: number, public next: ListNode | null = null) {}
}
function makeList(values: number[]): ListNode | null {
  let head: ListNode | null = null;
  for (let i = values.length - 1; i >= 0; i--) head = new ListNode(values[i], head);
  return head;
}
function toValues(head: ListNode | null): number[] {
  const out: number[] = [];
  for (; head !== null; head = head.next) out.push(head.value);
  return out;
}
function findIndex(head: ListNode | null, target: number): number {
  let i = 0;
  for (; head !== null; head = head.next, i++) if (head.value === target) return i;
  return -1;
}
function predecessor(sentinel: ListNode, index: number): ListNode {
  if (!Number.isInteger(index) || index < 0) throw new RangeError('index');
  let pred = sentinel;
  for (let i = 0; i < index; i++) {
    if (pred.next === null) throw new RangeError('index');
    pred = pred.next;
  }
  return pred;
}
function insertAt(head: ListNode | null, index: number, value: number): ListNode | null {
  const sentinel = new ListNode(0, head), pred = predecessor(sentinel, index);
  pred.next = new ListNode(value, pred.next);
  return sentinel.next;
}
function eraseAt(head: ListNode | null, index: number): ListNode | null {
  const sentinel = new ListNode(0, head), pred = predecessor(sentinel, index);
  const victim = pred.next;
  if (victim === null) throw new RangeError('index');
  pred.next = victim.next; victim.next = null;
  return sentinel.next;
}
function reverseList(head: ListNode | null): ListNode | null {
  let prev: ListNode | null = null;
  while (head !== null) {
    const successor: ListNode | null = head.next;
    head.next = prev; prev = head; head = successor;
  }
  return prev;
}
function mergeSorted(a: ListNode | null, b: ListNode | null): ListNode | null {
  const sentinel = new ListNode(0);
  let tail = sentinel;
  while (a !== null && b !== null) {
    if (a.value <= b.value) { tail.next = a; a = a.next; }
    else { tail.next = b; b = b.next; }
    tail = tail.next;
  }
  tail.next = a !== null ? a : b;
  return sentinel.next;
}
console.log(toValues(reverseList(makeList([10,20,30])))); // [30,20,10]

