  for(let p=head;p!==null;p=p.next) original.push(p);
  const result=reverseList(head), seen=[];
  let p=result;
  while(p!==null && seen.length<=original.length) { seen.push(p); p=p.next; }
  __check(title+' identity order',seen.length===original.length && seen.every((node,i)=>node===original[original.length-1-i]),true);
  __check(title+' payloads',seen.map(node=>node.value),values.slice().reverse());
  __check(title+' termination',p===null,true);
}

