int main() {
    vector<vector<int>> cases={{},{7},{4,4,9},{0,-1,2,3}};
    for (size_t k=0;k<cases.size();++k) {
        Node* head=make_list(cases[k]); vector<Node*> original;
        for(Node* p=head;p;p=p->next) original.push_back(p);
        Node* result=reverse_list(head); vector<Node*> seen;
        Node* p=result;
        while(p && seen.size()<=original.size()) { seen.push_back(p); p=p->next; }
        bool identity=seen.size()==original.size(), payload=identity;
        if(identity) for(size_t i=0;i<seen.size();++i) {
            identity=identity && seen[i]==original[original.size()-1-i];
            payload=payload && seen[i]->value==cases[k][cases[k].size()-1-i];
        }
        __check("identity "+to_string(k),identity,true);
        __check("payload "+to_string(k),payload,true);
        __check("termination "+to_string(k),p==nullptr,true);
        // The harness assumes allocated nodes remain live. Exercises must not delete them.
        // Delete the original ownership set exactly once, even after a wrong rewire.
        for(Node* node:original) delete node;
    }
    return 0;
}
